solution.solution.cpp:
#include <cstddef>

int* makeArray(std::size_t count, int fill)
{
    int* array{ new int[count] };
    for (std::size_t i{ 0 }; i < count; ++i)
    {
        array[i] = fill;
    }
    return array;
}

void destroyArray(int* array)
{
    delete[] array;
}

unitTests:
TEST("allocates and fills") { int* a{ makeArray(5, 7) }; CHECK(a != nullptr); if (a) { CHECK_EQ(a[0], 7); CHECK_EQ(a[4], 7); a[2] = 99; CHECK_EQ(a[2], 99); } destroyArray(a); }
TEST("nothing is leaked") { CHECK_NO_LEAK(int* a{ makeArray(1000, 1) }; destroyArray(a)); }
TEST("forgetting to destroy would leak (this is what the check catches)") { const xenon::HeapMark mark{}; int* a{ makeArray(10, 0) }; CHECK(a == nullptr || mark.leakedBytes() > 0); destroyArray(a); }

